import {
  AbsoluteFill,
  Img,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  staticFile,
  Easing,
} from "remotion";

const RUNGS = 7; // Number of rungs to climb
const RUNG_SPACING = 75; // Pixels between rungs
const FRAMES_PER_JUMP = 25; // Frames per jump (~0.83s at 30fps)
const PAUSE_FRAMES = 10; // Pause on each rung before next jump

export const LadderClimb: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Calculate which rung we're on or jumping to
  const framesPerStep = FRAMES_PER_JUMP + PAUSE_FRAMES;
  const currentStep = Math.floor(frame / framesPerStep);
  const frameInStep = frame % framesPerStep;

  // Clamp to max rungs
  const clampedStep = Math.min(currentStep, RUNGS - 1);
  const isJumping = frameInStep < FRAMES_PER_JUMP && clampedStep < RUNGS - 1 && currentStep <= RUNGS - 1;

  // Vertical positions for each rung (bottom to top)
  const bottomY = height - 180; // Starting position (bottom of ladder)
  const getYForRung = (rung: number) => bottomY - rung * RUNG_SPACING;

  // Current rung Y and next rung Y
  const fromRung = Math.min(clampedStep, RUNGS - 1);
  const toRung = Math.min(clampedStep + 1, RUNGS - 1);
  const fromY = getYForRung(currentStep >= RUNGS ? RUNGS - 1 : fromRung);
  const toY = getYForRung(toRung);

  // Smooth jump animation with spring
  let stickmanY: number;
  let stickmanX = width / 2; // Center horizontally

  if (currentStep >= RUNGS) {
    // Done climbing — stay at top
    stickmanY = getYForRung(RUNGS - 1);
  } else if (isJumping) {
    // Jumping phase — move UP with a spring
    const jumpProgress = spring({
      frame: frameInStep,
      fps,
      config: {
        damping: 14,
        stiffness: 120,
        mass: 0.8,
      },
    });

    // Vertical: interpolate from current rung to next
    stickmanY = interpolate(jumpProgress, [0, 1], [fromY, toY]);

    // Add a horizontal wobble during jump (slight side-to-side)
    const wobble = Math.sin(frameInStep * 0.5) * 8;
    stickmanX += wobble;

    // Add arc — character goes slightly left/right during jump
    const arcHeight = interpolate(
      jumpProgress,
      [0, 0.5, 1],
      [0, -30, 0],
      { extrapolateRight: "clamp" }
    );
    stickmanY += arcHeight;
  } else {
    // Pausing on a rung
    stickmanY = getYForRung(clampedStep);

    // Tiny idle bounce
    const bounce = Math.sin(frameInStep * 0.3) * 2;
    stickmanY += bounce;
  }

  // Ladder position (centered)
  const ladderX = width / 2;
  const ladderTop = getYForRung(RUNGS - 1) - 80;
  const ladderBottom = bottomY + 60;
  const ladderHeight = ladderBottom - ladderTop;

  // Scale for the stickman (make it smaller to fit rungs)
  const stickmanScale = 0.18;

  // Background gradient animation
  const bgHue = interpolate(frame, [0, 300], [220, 260], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        background: `linear-gradient(180deg, hsl(${bgHue}, 30%, 15%) 0%, hsl(${bgHue + 20}, 25%, 25%) 100%)`,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Title text */}
      <div
        style={{
          position: "absolute",
          top: 40,
          width: "100%",
          textAlign: "center",
          fontFamily: "'Inter', sans-serif",
          fontSize: 36,
          fontWeight: 800,
          color: "#ffffff",
          opacity: interpolate(frame, [0, 20], [0, 1], {
            extrapolateRight: "clamp",
          }),
          textShadow: "0 2px 20px rgba(0,0,0,0.5)",
        }}
      >
        🪜 Remotion Ladder Climb Test
      </div>

      {/* Ladder image */}
      <Img
        src={staticFile("images/ladder.png")}
        style={{
          position: "absolute",
          left: ladderX - 85,
          top: ladderTop - 20,
          width: 170,
          height: ladderHeight + 40,
          objectFit: "fill",
        }}
      />

      {/* Stick Figure */}
      <Img
        src={staticFile("images/stickman.png")}
        style={{
          position: "absolute",
          left: stickmanX - 60,
          top: stickmanY - 120,
          width: 120,
          height: 140,
          objectFit: "contain",
          // Make white background transparent
          mixBlendMode: "multiply",
          // Add slight rotation during jumps
          rotate: isJumping
            ? `${interpolate(frameInStep, [0, FRAMES_PER_JUMP], [-5, 5], { extrapolateRight: "clamp" })}deg`
            : "0deg",
        }}
      />

      {/* Rung counter */}
      <div
        style={{
          position: "absolute",
          bottom: 40,
          width: "100%",
          textAlign: "center",
          fontFamily: "'Inter', sans-serif",
          fontSize: 28,
          fontWeight: 700,
          color: "#ffffff",
          opacity: 0.8,
        }}
      >
        Rung: {Math.min(clampedStep + 1, RUNGS)} / {RUNGS}
        {currentStep >= RUNGS && " ✅ TOP!"}
      </div>

      {/* Particles/sparkle when reaching top */}
      {currentStep >= RUNGS && (
        <>
          {Array.from({ length: 12 }).map((_, i) => {
            const angle = (i / 12) * Math.PI * 2;
            const celebFrame = frame - RUNGS * framesPerStep;
            const radius = interpolate(celebFrame, [0, 40], [0, 120], {
              extrapolateRight: "clamp",
            });
            const particleOpacity = interpolate(
              celebFrame,
              [0, 20, 50],
              [0, 1, 0],
              { extrapolateRight: "clamp" }
            );

            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: stickmanX + Math.cos(angle) * radius - 6,
                  top: stickmanY - 60 + Math.sin(angle) * radius - 6,
                  width: 12,
                  height: 12,
                  borderRadius: "50%",
                  background:
                    i % 3 === 0
                      ? "#FFD700"
                      : i % 3 === 1
                        ? "#FF6B6B"
                        : "#4ECDC4",
                  opacity: particleOpacity,
                }}
              />
            );
          })}
        </>
      )}
    </AbsoluteFill>
  );
};

import "./index.css";
import { Composition } from "remotion";
import { LadderClimb } from "./LadderClimb";

const RUNGS = 7;
const FRAMES_PER_JUMP = 25;
const PAUSE_FRAMES = 10;
const TOTAL_FRAMES = RUNGS * (FRAMES_PER_JUMP + PAUSE_FRAMES) + 60; // + 60 for celebration

export const RemotionRoot: React.FC = () => {
  return (
    <Composition
      id="LadderClimb"
      component={LadderClimb}
      durationInFrames={TOTAL_FRAMES}
      fps={30}
      width={1080}
      height={1080}
    />
  );
};

